<template>
  <div>
    <el-tooltip
      placement="right-end"
      effect="light"
      content="点击可扫码获取账户信息"
    >
      <svgIcon
        @click="showPop"
        style="width: 90px; height: 90px; cursor: pointer; margin-left: 10px"
        :icon-class="chooseAuthType"
      ></svgIcon>
    </el-tooltip>
  </div>
</template>
<script>
import svgIcon from "@/components/SvgIcon/index.vue";
import Broadcast from "outDic/public/libs/iframeNesting/index";

export default {
  components: { svgIcon },
  data() {
    return {
      chooseAuthType: "浙政钉",
      broadcaster: null,
    };
  },

  methods: {
    showPop() {
      function openCenteredPopup(url, width, height) {
        var screenWidth = window.screen.width;
        var screenHeight = window.screen.height;
        var left = screenWidth / 2 - width / 2;
        var top = screenHeight / 2 - height / 2;
        window.open(
          url,
          "_blank",
          `width=${width},height=${height},left=${left},top=${top}`
        );
      }

      function getUrl(type) {
        let link = "";
        switch (type) {
          case "微信":
            return "https://open.weixin.qq.com/connect/qrconnect?appid=wxbdc5610cc59c1631&redirect_uri=https://element.eleme.cn/#/zh-CN/component/tooltip#attributes&response_type=code&scope=snsapi_login&state=3d6be0a4035d839573b04816624a415e#wechat_redirect";
          case "浙政钉":
            link =
              "https://login-pro.ding.zj.gov.cn/oauth2/auth.htm?response_type=code&client_id=lsyj_sm_dingoa&redirect_uri=https://lsjtj.linkcld.com:8008/tlxx-modules-system/system/login/dingTalkAuthCallback&scope=get_user_info&authType=QRCODE&embedMode=true";
            return `/libs/iframeNesting/index.html?iframeSrc=${encodeURIComponent(
              link
            )}&title=${encodeURIComponent("浙政钉扫码授权")}`;
        }
      }

      openCenteredPopup(getUrl(this.chooseAuthType), 500, 400);
    },

    listenBrowser() {
      this.broadcaster = new Broadcast();
      this.broadcaster.addListener((message) => {
        if (message.content) {
          this.$message.success(`浙政钉用户授权id:${message.content}`);
        }
      });
    },
  },

  mounted() {
    this.listenBrowser();
  },

  destroyed() {
    this.broadcaster.removeListeners();
  },
};
</script>
